// TH16 v1.00a st04bs.ecl.txt BossCard3 (spell 42-45) -> task th16_s4_b6.
// Source entry :810-879; dependency BossCard3_at :881-965.
// Source clock: timerReset :820 is t=0, first volley at the "+60" label :850.

const TIME_LIMIT: int = 2584;
const OPENING_BUFFER: int = 120;
const SPELL_ID: int = 42;

// TH16 type 25 -> approved TH16 alias of the identical slot (bullet-types.md).
const TH16_FIREBALL_RED: int = 752;
const BULLET_COLOR: int = 0;

// :898 etSpeed(0,0.1,1.0) with etCount layers=1 -> only s0 is used.
const BULLET_SPEED: fx = 0.1fx;
// :920 etOffsetAbs(0,0,448): the emitters sit on the world bottom edge.
const SPAWN_Y: fx = 448fx;

// BossCard3_at EX records (:899,:900,:918,:919,:943,:953,:954,:955):
//   ANIM(a=1) -> WAIT 120 -> ACCEL 200 (dir = bullet angle)
//   -> WAIT 10 -> ACCEL 100 (dir +pi/2) -> WAIT 100 -> ACCEL 100 (dir +pi/2)
// Spawn phase (ANIM) is omitted per transcription-policy; its -4*velocity entry
// displacement is kept at the fire point. ACCEL enters with a fixed direction,
// so it maps to set_gravity(r*cos q, r*sin q) and the expiry clears both axes.
xformdef CARD3_EX(r1: fx, r2a: fx, r2b: fx) {
    @120 add_speed(0fx);                                  // WAIT 120
    @200 set_gravity(at_effect(r1 * cos($self_angle)),
                     at_effect(r1 * sin($self_angle)));   // ACCEL 200, s<=-999990 keeps bullet angle
    set_gravity(0fx, 0fx);
    @10 add_speed(0fx);                                   // WAIT 10
    @100 set_gravity(0fx, r2a);                           // ACCEL 100, s=1.5707964
    set_gravity(0fx, 0fx);
    @100 add_speed(0fx);                                  // WAIT 100
    @100 set_gravity(0fx, r2b);                           // ACCEL 100, s=1.5707964
    set_gravity(0fx, 0fx);
}

// :0924-0963 fan of one etOn: aim mode 1, one layer, alternating path offsets
// F(N,i) of aim-modes.md. Each bullet spawns 4*velocity behind its emit point
// along its own angle (ANIM a=1 entry displacement).
sub card3_fan(x0: fx, base: angle, n: int, delta: int, r1: fx, r2a: fx, r2b: fx) {
    for i in 0..n {
        var off: int = (i / 2) * delta + delta / 2;
        if n % 2 == 1 { off = ((i + 1) / 2) * delta; }
        if i % 2 != 0 { off = -off; }
        var a: angle = base + (off as angle);
        var sx: fx = x0 - 0.4fx * cos(a);
        var sy: fx = SPAWN_Y - 0.4fx * sin(a);
        _ = fire(TH16_FIREBALL_RED, BULLET_COLOR, sx, sy, BULLET_SPEED, a,
                 CARD3_EX(r1, r2a, r2b), none);
    }
}

// :881-965 BossCard3_at. Six waves two fans each; %A 192 -> 22 step -34,
// 10 frames between waves. Random reads per wave follow the source order:
// angle jitter (RANDF2), slot2 RANDF, slot4 RANDF, slot6 RANDF,
// two etOffset RANDF2.
sub card3_volley() {
    var count: int = 6;        // :0887-0895  !E3 !N4 !H5 !LO6
    var delta: int = 2979;     // :0925-0932  E 45deg, N/H 22.5deg, L 16.36deg (BAM)
    var jitter: int = 910;     // :0933-0940  E 0, N +-1deg, H +-4deg, L +-5deg (BAM)
    var r2base: fx = 0.022fx;  // :0944-0951 / :0955 ACCEL scalar
    var rank: int = global(GVAR_RANK);
    if rank == RANK_EASY {
        count = 3;
        delta = 8192;
        jitter = 0;
        r2base = 0.02fx;
    } else if rank == RANK_NORMAL {
        count = 4;
        delta = 4096;
        jitter = 182;
        r2base = 0.02fx;
    } else if rank == RANK_HARD {
        count = 5;
        delta = 4096;
        jitter = 728;
    }
    var bx: fx = 192fx;        // :0921 %A = 192, :0960 -= 34
    for wave in 0..6 {         // :0922 diffI($B,6,6,6,6), :0963 if ($B--)
        var aoff: int = 0;
        if jitter != 0 {
            aoff = (rand(65536) - 32768) * jitter / 32768;
        }
        var base_a: angle = -90deg + (aoff as angle);
        var r1: fx = 0.01fx + 0.003fx * ((rand(16384) as fx) / 16384fx);
        var r2a: fx = r2base + 0.001fx * ((rand(16384) as fx) / 16384fx);
        var r2b: fx = r2base + 0.001fx * ((rand(16384) as fx) / 16384fx);
        var x1: fx = bx + (((rand(32768) - 16384) as fx) / 16384fx) * 7fx;
        card3_fan(x1, base_a, count, delta, r1, r2a, r2b);
        var x2: fx = -bx + (((rand(32768) - 16384) as fx) / 16384fx) * 7fx;
        card3_fan(x2, base_a, count, delta, r1, r2a, r2b);
        bx = bx - 34fx;
        wait(10);              // :0961
    }
}

// --- moveRand(60,4,1.0) with moveLimit(0,144,288,128); see movement.md recipe.
// int slot0 = next-step count, fx0/fx1 = logical unit vector. Limits clamp to
// x in [-144,144], y in [80,208]; the direction pick uses the inner quarter
// region x +-72, y 112..176.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -144fx { nx = -144fx; }
    if nx > 144fx { nx = 144fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 208fx { ny = 208fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card3_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card3_move_rand() {
    // Signed unit random * pi, kept as unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -72fx {
        a = r / 3;
    } else if $self_x > 72fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 176fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card3_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// Boss main task. Frame boxes from Boss() context: :027 setHurtbox(40,40),
// :028 setHitbox(48,48); entry position inherited from Boss3 (:014 movePos
// (0,128) is the last documented boss position before this card).
async sub card3_boss() {
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);   // :845 movePosTime(60,4,0,144)
    wait(60);                                 // :850 "+60"
    var pause: int = 90;                      // :0859-0867 !E/!N 160, !H 120, !LO 90
    var rank: int = global(GVAR_RANK);
    if rank == RANK_EASY || rank == RANK_NORMAL { pause = 160; }
    else if rank == RANK_HARD { pause = 120; }
    loop {
        // :839 2460-frame interrupt window is the card's own source window;
        // the shell timer ends the segment at the same point.
        if $self_age >= 2460 { return; }
        card3_volley();        // :0858 @BossCard3_at()
        wait(pause);           // :0868 wait([-1])
        card3_move_rand();     // :0869 moveRand(60,4,1.0)
        card_wait(60);         // :0870 wait(60)
    }
}

async sub card3_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2300, 0, 0, 0, card3_boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, SPELL_ID, card3_pattern, TIME_LIMIT, 100000, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
